INSERT INTO ehive_records (object_record_id, object_number, name, object_type, place_made, maker, location, perspective, public_access, fields_json, source_file) VALUES ('1831726', 'M12', 'Door Sign, Dorrigo Hotel', 'Signs', 'Melbourne', 'Testro Bros. Pty. Ltd.', NULL, 'HISTORY', 0, '{"object_number":"M12","name":"Door Sign, Dorrigo Hotel","object_type":"Signs","dublin_core":"Physical Object","brief_description":"Plastic coated printed door sign used at the Dorrigo Hotel. The sign features an illustration of a woman wearing a white hostess apron and holding signs, one titled ''Hotel Services'' and the other ''Service Directory''. The text includes mention of Dorrigo businesses, including The Mercia Beauty Salon, Bill Taylor Butcher and Hollingworth Bros. Garage and Service Station.  The sign has a purpose made hole at the top and bottom for securing to the back of a room door with screws. \n\nThe Dorrigo Hotel was built in 1925 by Michael Feros.","web_public_description":"Plastic coated printed door sign used at the Dorrigo Hotel. The sign features an illustration of a woman wearing a white hostess apron and holding signs, one titled ''Hotel Services'' and the other ''Service Directory''. The text includes mention of Dorrigo businesses, including The Mercia Beauty Salon, Bill Taylor Butcher and Hollingworth Bros. Garage and Service Station.  The sign has a purpose made hole at the top and bottom for securing to the back of a room door with screws. \n\nThe Dorrigo Hotel was built in 1925 by Michael Feros.","primary_creator_maker":"Testro Bros. Pty. Ltd.","primary_creator_maker_role":"Manufacturer","date_made":"c1950s","place_made":"Melbourne","medium_description":"Metal, paper, plastic","inscription":"Printed at end of text ''Especially designed and published by Testro Bros. Pty. Ltd./ 266 Flinders Street, Melbourne. Phone Cent. 1659''","association_keyword":"Hotels","general_notes_object":"Date has been based on illustration style and materials used. All businesses mentioned were operating in the early 1950s (Trove search).","catalogued_date":"30/08/2023","comments":"DDM_M12-col.dng\nDDM_M12-col.tif\nDDM_M12-d01.dng\nDDM_M12-d01.tif\nDDM_M12-d02.dng\nDDM_M12-d02.tif\nDDM_M12.md5","comments_date":"22/08/2023","comments_person":"A Long","general_flag_admin":"Digitised"}', 'secondreport_xml_7f337cc921094b62b3bdd0725e70ec7c.xml');
INSERT INTO ehive_records (object_record_id, object_number, name, object_type, place_made, maker, location, perspective, public_access, fields_json, source_file) VALUES ('1755421', 'M43', 'Cedar Springboard', 'Equipment', NULL, NULL, 'Main south west wall', 'HISTORY', 0, '{"object_number":"M43","accession_date":"09/09/1981","name":"Cedar Springboard","object_type":"Equipment","dublin_core":"Physical Object","brief_description":"Cedar springboard used for tree felling on the Dorrigo Plateau. Belonged to the Schmidt family of Mountain Top.","web_public_description":"Cedar springboard used for tree felling on the Dorrigo Plateau. Belonged to the Schmidt family of Mountain Top.","location":"Main south west wall","location_notes":"Near front desk.","location_history":"Main south west wall","location_history_date":"11/03/2023","medium_description":"Wood, metal","measurement_description":"103cm H, 15cm W, 4cm Deep","association_keyword":"Timber","general_notes_object":"A very important piece of equipment used in tree felling. Owned by Vera Schmidt","catalogued_date":"21/06/2023","cataloguer":"Robyn Cork","general_notes_acquisition":"Donated by: G Hillary, 1981","credit_line":"Donor: G Hillary, 1981","comments":"DDM_M43-d01.dng\nDDM_M43-d01.tif\nDDM_M43-d02.dng\nDDM_M43-d02.tif\nDDM_M43.md5","comments_date":"17/08/2023","comments_person":"A Long","general_flag_admin":"Digitised","current_condition_description":"Well used, but complete."}', 'secondreport_xml_7f337cc921094b62b3bdd0725e70ec7c.xml');
INSERT INTO ehive_records (object_record_id, object_number, name, object_type, place_made, maker, location, perspective, public_access, fields_json, source_file) VALUES ('1755443', 'M44', 'Illuminated Address, Lady Workers Deer Vale', 'Illuminated addresses', 'Sydney', 'John Sands Ltd', 'Research Room', 'HISTORY', 0, '{"object_number":"M44","accession_date":"1981","name":"Illuminated Address, Lady Workers Deer Vale","object_type":"Illuminated addresses","dublin_core":"Physical Object","brief_description":"Hand painted illuminated address contained within a dark brown mount and carved wooden frame. At the top is a Rising Sun emblem and ''Australian Commonwealth Military Forces'' text with a laurel wreath. Below this are the Union Jack and Australian Flags, suspended from flagpoles with flowering wattles in the background. Below the address text is a Red Cross emblem. \n\nThe illuminated address reads: ''THE LADY WORKERS OF DEER VALE\nOn behalf of the RETURNED SOLDIERS of this locality, we desire to express our appreciation of your noble and untiring efforts on our behalf during the Great War, 1914–1919. \nYour splendid spirit and noble example are worthy of, and have won our highest commendation, and you will always have the great satisfaction of knowing that you did all that was humanly possible in the time of your Country''s need.  \nThe result of your splendid work was to be found in every theatre of War in which the members of the Australian Imperial Forces were engaged, and carried to us the memory of our Homeland. \nWe trust your future will be happy and prosperous, and that you all will long be spared to enjoy the freedom and privilege of our Great Empire.  \nWe tender the sincerest appreciation and gratitude of the \nDEER VALE BOYS''. \n\nLady War Workers Groups were created during the First World War. They raised funds for serving soldiers and organised welcome home functions. The Deer Vale lady war workers group was the Deer Vale branch of the Red Cross. The address was presented at a ''complimentary social'' organised by the Deer Vale soldiers, and held in the Deer Vale Hall on Wednesday 27 October 1920. Deer Vale is a small community located west of Dorrigo.","web_public_description":"Hand painted illuminated address contained within a dark brown mount and carved wooden frame. At the top is a Rising Sun emblem and ''Australian Commonwealth Military Forces'' text with a laurel wreath. Below this are the Union Jack and Australian Flags, suspended from flagpoles with flowering wattles in the background. Below the address text is a Red Cross emblem. \n\nThe illuminated address reads: ''THE LADY WORKERS OF DEER VALE\nOn behalf of the RETURNED SOLDIERS of this locality, we desire to express our appreciation of your noble and untiring efforts on our behalf during the Great War, 1914–1919. \nYour splendid spirit and noble example are worthy of, and have won our highest commendation, and you will always have the great satisfaction of knowing that you did all that was humanly possible in the time of your Country''s need.  \nThe result of your splendid work was to be found in every theatre of War in which the members of the Australian Imperial Forces were engaged, and carried to us the memory of our Homeland. \nWe trust your future will be happy and prosperous, and that you all will long be spared to enjoy the freedom and privilege of our Great Empire.  \nWe tender the sincerest appreciation and gratitude of the \nDEER VALE BOYS''. \n\nLady War Workers Groups were created during the First World War. They raised funds for serving soldiers and organised welcome home functions. The Deer Vale lady war workers group was the Deer Vale branch of the Red Cross. The address was presented at a ''complimentary social'' organised by the Deer Vale soldiers, and held in the Deer Vale Hall on Wednesday 27 October 1920. Deer Vale is a small community located west of Dorrigo.","primary_creator_maker":"John Sands Ltd","date_made":"1920","place_made":"Sydney","location":"Research Room","location_history":"Research Room","location_history_date":"15/06/2023","medium_description":"Wood, paper, paint, ink","inscription":"Printed left lower corner ''JOHN SANDS LTD. SYDNEY''.","measurement_description":"Frame:  765mm L, 625mm W","association_keyword":"Wars","catalogued_date":"15/06/2023","cataloguer":"Robyn Cork","general_notes_acquisition":"Donated by:\nDeer Vale Community","credit_line":"Donor: Deer Vale Community, 1981","comments":"DDM_M44-d01.dng\nDDM_M44-d01.tif\nDDM_M44-d02.dng\nDDM_M44-d02.tif\nDDM_M44-d03.dng\nDDM_M44-d03.tif\nDDM_M44.md5","comments_date":"28/08/2023","comments_person":"A Long","general_flag_admin":"Digitised","current_condition_description":"Fair."}', 'secondreport_xml_7f337cc921094b62b3bdd0725e70ec7c.xml');
INSERT INTO ehive_records (object_record_id, object_number, name, object_type, place_made, maker, location, perspective, public_access, fields_json, source_file) VALUES ('1841769', 'M239', 'Trophy, Davis Cup', 'Trophies', NULL, NULL, NULL, 'HISTORY', 0, '{"object_number":"M239","name":"Trophy, Davis Cup","object_type":"Trophies","dublin_core":"Physical Object","brief_description":"Silver plate cup trophy on a wooden base. The cup is engraved ''DAVIS CUP/ REPLACED BY LEIGH''. Attached around the base are a number of small  silver shields each engraved with a school name and year/s.  \n\nThe Davis Cup trophy was contested each year by schools at the District Schools'' Athletic Meeting. The sports day was held at the Dorrigo showground. \n\nThe cup was named after the person who presented it Mr. J. H. Davis. It was decided to use the cup for competition between individual schools, Dorrigo excepted. The Davis Cup was first presented in  August 1928 to West Dorrigo School. \n\nIn 1933, the original Davis Cup was destroyed by a fire at the residence of Mr. Hogan. The holder of the cup at the time was Leigh School and the parents and school teacher from Leigh, Mr. Lorimer, raised funds to replace the cup with this one.","web_public_description":"Silver plate cup trophy on a wooden base. The cup is engraved ''DAVIS CUP/ REPLACED BY LEIGH''. Attached around the base are a number of small  silver shields each engraved with a school name and year/s.  \n\nThe Davis Cup trophy was contested each year by schools at the District Schools'' Athletic Meeting. The sports day was held at the Dorrigo showground. \n\nThe cup was named after the person who presented it Mr. J. H. Davis. It was decided to use the cup for competition between individual schools, Dorrigo excepted. The Davis Cup was first presented in  August 1928 to West Dorrigo School. \n\nIn 1933, the original Davis Cup was destroyed by a fire at the residence of Mr. Hogan. The holder of the cup at the time was Leigh School and the parents and school teacher from Leigh, Mr. Lorimer, raised funds to replace the cup with this one.","date_made":"1930s","association_keyword":"Schools","general_notes_object":"References:\nDon Dorrigo Gazette, Friday 10 August 1928, p3\nDon Dorrigo Gazette, Friday 29 September 1933, p2","catalogued_date":"16/06/2023","comments":"DDM_M239-col.dng\nDDM_M239-col.tif\nDDM_M239-d01.dng\nDDM_M239-d01.tif\nDDM_M239-d02.dng\nDDM_M239-d02.tif\nDDM_M239-d03.dng\nDDM_M239-d03.tif\nDDM_M239-d04.dng\nDDM_M239-d04.tif\nDDM_M239-d05.dng\nDDM_M239-d05.tif\nDDM_M239-d06.dng\nDDM_M239-d06.tif\nDDM_M239-d07.dng\nDDM_M239-d07.tif\nDDM_M239-d08.dng\nDDM_M239-d08.tif\nDDM_M239.md5","comments_date":"17/08/2023","comments_person":"A Long","general_flag_admin":"Digitised"}', 'secondreport_xml_7f337cc921094b62b3bdd0725e70ec7c.xml');
INSERT INTO ehive_records (object_record_id, object_number, name, object_type, place_made, maker, location, perspective, public_access, fields_json, source_file) VALUES ('1755390', 'M278', 'Bottle, Bailey''s Mountain Mist', 'Bottles', NULL, NULL, 'Kitchen Display', 'HISTORY', 0, '{"object_number":"M278","name":"Bottle, Bailey''s Mountain Mist","object_type":"Bottles","dublin_core":"Physical Object","brief_description":"Pale green tall cordial bottle, with narrow neck and embossed text ''BAILEY''S MOUNTAIN MIST'', in the centre of the text are embossed symbols representing mountains.","web_public_description":"Pale green tall cordial bottle, with narrow neck and embossed text ''BAILEY''S MOUNTAIN MIST'', in the centre of the text are embossed symbols representing mountains.","location":"Kitchen Display","location_history":"Kitchen Display","location_history_date":"16/06/2023","medium_description":"Glass","inscription":"Embossed near front base ''THIS BOTTLE ALWAYS REMAINS/THE PROPERTY OF/W H BAILEY DORRIGO''.","measurement_description":"300mm H, 80mm Base","association_keyword":"Factories","catalogued_date":"21/06/2023","cataloguer":"Robyn Cork","comments":"DDM_M278-d01.dng\nDDM_M278-d01.tif\nDDM_M278-d02.dng\nDDM_M278-d02.tif\nDDM_M278-d03.dng\nDDM_M278-d03.tif\nDDM_M278.md5","comments_date":"28/08/2023","comments_person":"A Long","general_flag_admin":"Digitised","current_condition_description":"Fair.  Some fine crakes radiating up from base."}', 'secondreport_xml_7f337cc921094b62b3bdd0725e70ec7c.xml');
INSERT INTO ehive_records (object_record_id, object_number, name, object_type, place_made, maker, location, perspective, public_access, fields_json, source_file) VALUES ('1755346', 'M436', 'Charcoal Cooler', 'Coolers', NULL, NULL, 'Verandah', 'HISTORY', 0, '{"object_number":"M436","name":"Charcoal Cooler","object_type":"Coolers","dublin_core":"Physical Object","brief_description":"Charcoal cooler comprising a timber frame around a metal cupboard with wire netting holding charcoal in place.  There is a metal tray on top.\n\nA charcoal cooler is a storage chamber constructed from locally available materials and is used to store perishable commodities under cool temperatures. As warm, dry air passes through the moist charcoal, it draws energy from its surroundings which produces a cooling effect. Charcoal Coolers were and are still used, particularly in rural areas where households are not connected to electricity.","web_public_description":"Charcoal cooler comprising a timber frame around a metal cupboard with wire netting holding charcoal in place.  There is a metal tray on top.\n\nA charcoal cooler is a storage chamber constructed from locally available materials and is used to store perishable commodities under cool temperatures. As warm, dry air passes through the moist charcoal, it draws energy from its surroundings which produces a cooling effect. Charcoal Coolers were and are still used, particularly in rural areas where households are not connected to electricity.","location":"Verandah","location_history":"Verandah","location_history_date":"11/03/2023","medium_description":"Wood, metal, charcoal","measurement_description":"106cm H, 69cm W, 57cm D","association_keyword":"Household objects","catalogued_date":"21/06/2023","cataloguer":"Robyn Cork","general_notes_acquisition":"Donated by:  \nMuriel and Ray Foster.","credit_line":"Donors: M & R Foster","comments":"DDM_M436-col.dng\nDDM_M436-col.tif\nDDM_M436-d01.dng\nDDM_M436-d01.tif\nDDM_M436-d02.dng\nDDM_M436-d02.tif\nDDM_M436-d03.dng\nDDM_M436-d03.tif\nDDM_M436.md5","comments_date":"17/08/2023","comments_person":"A Long","general_flag_admin":"Digitised","current_condition_description":"Well used, but mostly complete."}', 'secondreport_xml_7f337cc921094b62b3bdd0725e70ec7c.xml');
INSERT INTO ehive_records (object_record_id, object_number, name, object_type, place_made, maker, location, perspective, public_access, fields_json, source_file) VALUES ('1754068', 'M521', 'Wooden Tray', 'Trays', NULL, 'Les Mills', 'Kitchen Display', 'HISTORY', 0, '{"object_number":"M521","name":"Wooden Tray","object_type":"Trays","dublin_core":"Physical Object","brief_description":"Tray made from Dorrigo softwoods, including Red Cedar, Silky Oak, Prickly Ash and Sassafras.  At each corner are protective pieces cut from the body of Harry Shaw''s Mail Car that carried passengers and mail from Raleigh to Dorrigo. Turned wooden handles have been screwed into place at each end.","web_public_description":"Tray made from Dorrigo softwoods, including Red Cedar, Silky Oak, Prickly Ash and Sassafras.  At each corner are protective pieces cut from the body of Harry Shaw''s Mail Car that carried passengers and mail from Raleigh to Dorrigo. Turned wooden handles have been screwed into place at each end.","primary_creator_maker":"Les Mills","date_made":"1949","location":"Kitchen Display","location_notes":"On table.","location_history":"Kitchen Display","medium_description":"Wood, metal","measurement_description":"90mm H, 460mm L, 320mm W","association_keyword":"Timber","general_notes_object":"Information from typed object label.","catalogued_date":"16/06/23","cataloguer":"Robyn Cork","general_notes_acquisition":"Donated by:\nBob and Roma Gater\nNowra NSW","credit_line":"Donors:  B and R Gater","comments":"DDM_M521-d01.dng\nDDM_M521-d01.tif\nDDM_M521-d02.dng\nDDM_M521-d02.tif\nDDM_M521.md5","comments_date":"28/08/2023","comments_person":"A Long","general_flag_admin":"Digitised","current_condition_description":"Fair, adhesive tape residue in centre of tray."}', 'secondreport_xml_7f337cc921094b62b3bdd0725e70ec7c.xml');
INSERT INTO ehive_records (object_record_id, object_number, name, object_type, place_made, maker, location, perspective, public_access, fields_json, source_file) VALUES ('1754074', 'M654a', 'Women''s Red Swimsuit', 'Swimsuits', 'Australia', 'Black Lance', 'Bedroom', 'HISTORY', 0, '{"object_number":"M654a","accession_date":"September 1988","name":"Women''s Red Swimsuit","object_type":"Swimsuits","dublin_core":"Physical Object","brief_description":"A knitted woolen women''s swimsuit in a sheath style with centre panels front and back. The fabric is red textured wool.  There is a cross over front at bust and narrow shoulder straps.  At the lower left side is an appliqued label ''Black Lance''.\n\nWorn by Eileen Mary Yeomans, donors mother, [d. August 1987] when at the beach at Port Macquarie.\n\nPeter O''Sullivan became the first Australian designer and manufacturer to successfully export to the United States. One of his innovations was the small skirt across the front of both men''s and women''s swimsuits known as the ''modesty panel''. O''Sullivan''s ''modesty panel'' became a feature of Australian and international swimwear fashions right up until the 1970s. His Black Lance swimwear range in the 1930s featured low cut backs, fashionable colours and decorative flourishes.","web_public_description":"A knitted woolen women''s swimsuit in a sheath style with centre panels front and back. The fabric is red textured wool.  There is a cross over front at bust and narrow shoulder straps.  At the lower left side is an appliqued label ''Black Lance''.\n\nWorn by Eileen Mary Yeomans, donors mother, [d. August 1987] when at the beach at Port Macquarie.\n\nPeter O''Sullivan became the first Australian designer and manufacturer to successfully export to the United States. One of his innovations was the small skirt across the front of both men''s and women''s swimsuits known as the ''modesty panel''. O''Sullivan''s ''modesty panel'' became a feature of Australian and international swimwear fashions right up until the 1970s. His Black Lance swimwear range in the 1930s featured low cut backs, fashionable colours and decorative flourishes.","primary_creator_maker":"Black Lance","primary_creator_maker_role":"Manufacturer","date_made":"1930s","place_made":"Australia","location":"Bedroom","location_history":"Bedroom","location_history_date":"15/06/23","location_history_notes":"Wardrobe","medium_description":"Textile","inscription":"Labels stitched to inner front seam ''40'' and ''BLACK LANCE''/KNITTED WEAR''","measurement_description":"Including straps 80mmL","association_keyword":"Swimming","general_notes_object":"References:\nhttps://collections.sea.museum/objects/39507/womens-black-lance-swimsuit, accessed on 06/09/2023","catalogued_date":"16/06/23","cataloguer":"Robyn Cork","general_notes_acquisition":"Donated by:  Amber Harrigan","credit_line":"Donor: A Harrigan, 1988","comments":"DDM_M654a-d01.dng\nDDM_M654a-d01.tif\nDDM_M654a-d02.dng\nDDM_M654a-d02.tif\nDDM_M654a.md5","comments_date":"15/08/2023","comments_person":"A Long","general_flag_admin":"Digitised","current_condition_description":"Poor.  Fabric is shedding fibres, small insect holes at front.  Fabric is matted particularly in the crotch area."}', 'secondreport_xml_7f337cc921094b62b3bdd0725e70ec7c.xml');
INSERT INTO ehive_records (object_record_id, object_number, name, object_type, place_made, maker, location, perspective, public_access, fields_json, source_file) VALUES ('1755437', 'M654b', 'Bathing Cap', 'Caps', NULL, NULL, 'Bedroom', 'HISTORY', 0, '{"object_number":"M654b","accession_date":"September 1988","name":"Bathing Cap","object_type":"Caps","dublin_core":"Physical Object","brief_description":"Cotton bathing cap in a helmet shape, has panels at each side stitched into a panel running from the back neck to forehead.  Two long narrow ties attached to the lower edge of the cap enable it to be tied under the chin.\n\nWorn by Eileen Mary Yeomans (donor''s mother) [d. Aug 1987] when swimming at the beach at Port Macquarie.","web_public_description":"Cotton bathing cap in a helmet shape, has panels at each side stitched into a panel running from the back neck to forehead.  Two long narrow ties attached to the lower edge of the cap enable it to be tied under the chin.\n\nWorn by Eileen Mary Yeomans (donor''s mother) [d. Aug 1987] when swimming at the beach at Port Macquarie.","date_made":"1930s","location":"Bedroom","location_history":"Bedroom","location_history_date":"15/06/2023","location_history_notes":"Wardrobe","medium_description":"Textiles","measurement_description":"220mm L, Ties 40mm L.","association_keyword":"Swimming","catalogued_date":"21/06/2023","cataloguer":"Robyn Cork","general_notes_acquisition":"Donated by:  \nAmber Harrigan, September 1988.","credit_line":"Donor: A Harrigan, 1988","provenance_details":"Worn by Mrs Yeomans (Amber Harrigan''s mother) when at the beach at Port Macquarie. [d Aug 1987].","comments":"DDM_M654b.md5\nDDM_M654b-col.dng\nDDM_M654b-col.tif\nDDM_M654b-p001.dng\nDDM_M654b-p001.tif\nDDM_M654b-p002.dng\nDDM_M654b-p002.tif","comments_date":"15/08/2023","comments_person":"A Long","general_flag_admin":"Digitised","current_condition_description":"Fair."}', 'secondreport_xml_7f337cc921094b62b3bdd0725e70ec7c.xml');
INSERT INTO ehive_records (object_record_id, object_number, name, object_type, place_made, maker, location, perspective, public_access, fields_json, source_file) VALUES ('1831724', 'M677', 'Butter Box, "Orrigo" Butter', 'Boxes', NULL, NULL, 'Verandah', 'HISTORY', 0, '{"object_number":"M677","name":"Butter Box, \"Orrigo\" Butter","object_type":"Boxes","dublin_core":"Physical Object","brief_description":"Wooden butter box for ''ORRIGO'' butter. The box has a stencilled design and information on the front side.  Each of the panels is nailed in place except for the lid. The box held 56lbs nett of butter.  Orrigo butter was made by the Dorrigo Co-operative Dairy Co Ltd.","web_public_description":"Wooden butter box for ''ORRIGO'' butter. The box has a stencilled design and information on the front side.  Each of the panels is nailed in place except for the lid. The box held 56lbs nett of butter.  Orrigo butter was made by the Dorrigo Co-operative Dairy Co Ltd.","location":"Verandah","location_history":"Verandah","location_history_date":"30/07/2023","location_history_notes":"Dairy display","medium_description":"Wood, ink","measurement_description":"330m H, 340mm L, 335mm W","association_keyword":"Agriculture","catalogued_date":"30/07/2023","cataloguer":"Robyn Cork","general_notes_acquisition":"Donated by:\nDorrigo Agricultural Society","credit_line":"Donor: Dorrigo Agricultural Society","comments":"DDM_M677-d01.dng\nDDM_M677-d01.tif\nDDM_M677-d02.dng\nDDM_M677-d02.tif\nDDM_M677-d03.dng\nDDM_M677-d03.tif\nDDM_M677-d04.dng\nDDM_M677-d04.tif\nDDM_M677-d05.dng\nDDM_M677-d05.tif\nDDM_M677.md5","comments_date":"17/08/2023","comments_person":"A Long","general_flag_admin":"Digitised","current_condition_description":"Fair."}', 'secondreport_xml_7f337cc921094b62b3bdd0725e70ec7c.xml');
INSERT INTO ehive_records (object_record_id, object_number, name, object_type, place_made, maker, location, perspective, public_access, fields_json, source_file) VALUES ('1831718', 'M1020', 'Nameplate, Miss G M Sawtell', 'Plaques', NULL, NULL, 'Music Display', 'HISTORY', 0, '{"object_number":"M1020","name":"Nameplate, Miss G M Sawtell","object_type":"Plaques","dublin_core":"Physical Object","brief_description":"Brass nameplate with black text ''Miss G. M. SAWTELL/ (A.L.C.M. L.L.C.M.)/ TEACHER OF/ PIANO, THEORY & HARMONY''. There are four screw holes, one in each corner. The back of the nameplate is blank. \n\nUsed by Gladys (Glady) Myrtle Sawtell [1902-1980].","web_public_description":"Brass nameplate with black text ''Miss G. M. SAWTELL/ (A.L.C.M. L.L.C.M.)/ TEACHER OF/ PIANO, THEORY & HARMONY''. There are four screw holes, one in each corner. The back of the nameplate is blank. \n\nUsed by Gladys (Glady) Myrtle Sawtell [1902-1980].","location":"Music Display","location_history":"Music Display","location_history_date":"15/06/2023","location_history_notes":"On piano","medium_description":"Metal, paint","measurement_description":"335mm L, 180mm W","association_keyword":"Music","catalogued_date":"15/06/2023","comments":"DDM_M1020-col.dng\nDDM_M1020-col.tif\nDDM_M1020-d01.dng\nDDM_M1020-d01.tif\nDDM_M1020-d02.dng\nDDM_M1020-d02.tif\nDDM_M1020.md5","comments_date":"28/08/2023","comments_person":"A Long","general_flag_admin":"Digitised"}', 'secondreport_xml_7f337cc921094b62b3bdd0725e70ec7c.xml');
INSERT INTO ehive_records (object_record_id, object_number, name, object_type, place_made, maker, location, perspective, public_access, fields_json, source_file) VALUES ('1831711', 'M1055a', 'Plaque, Orient Line Award', 'Plaques', NULL, NULL, 'Verandah', 'HISTORY', 0, '{"object_number":"M1055a","name":"Plaque, Orient Line Award","object_type":"Plaques","dublin_core":"Physical Object","brief_description":"Circular bronze plaque mounted on a circular time frame and contained within a blue presentation timber frame. The plaque is embossed with text ''ORIENT LINE AWARD FOR EXPORT BUTTER''. The centre of the plaque is embossed with the Orient Line''s coat of arms and motto ''PAR NON LENINA SOCEATAS''. Orient Line was also known as the Orient Steam Navigation Company. \n\nOne of four awards presented to the Dorrigo Butter Factory for securing highest aggregate points for their export butter. The factory won the award four times between 1948 and 1964.","web_public_description":"Circular bronze plaque mounted on a circular time frame and contained within a blue presentation timber frame. The plaque is embossed with text ''ORIENT LINE AWARD FOR EXPORT BUTTER''. The centre of the plaque is embossed with the Orient Line''s coat of arms and motto ''PAR NON LENINA SOCEATAS''. Orient Line was also known as the Orient Steam Navigation Company. \n\nOne of four awards presented to the Dorrigo Butter Factory for securing highest aggregate points for their export butter. The factory won the award four times between 1948 and 1964.","date_made":"1948-1964","location":"Verandah","location_history":"Verandah","location_history_notes":"Dairy display","medium_description":"Metal, wood","measurement_description":"Frame: 300mm H, 65mm W\nPlaque: 10mm H, 230mm W\nWooden Mount: 20mm H, 240mm W","association_keyword":"Agriculture","general_notes_object":"References:\nhttps://en.wikipedia.org/wiki/Orient_Steam_Navigation_Company, accessed on 15/06/2023","catalogued_date":"15/06/2023","cataloguer":"Robyn Cork","general_notes_acquisition":"Donated by:\nPhil Shaw \nex Manager of Dorrigo Butter Factory","credit_line":"Donor: P Shaw","comments":"DDM_M1055a-col.dng\nDDM_M1055a-col.tif\nDDM_M1055a-d01.dng\nDDM_M1055a-d01.tif\nDDM_M1055a.md5","comments_date":"28/08/2023","comments_person":"A Long","general_flag_admin":"Digitised","current_condition_description":"Good."}', 'secondreport_xml_7f337cc921094b62b3bdd0725e70ec7c.xml');
INSERT INTO ehive_records (object_record_id, object_number, name, object_type, place_made, maker, location, perspective, public_access, fields_json, source_file) VALUES ('1838513', 'M1089', 'Butter Box Lid, Norco Co-Op Ltd', 'Boxes', NULL, NULL, 'Verandah', 'HISTORY', 0, '{"object_number":"M1089","name":"Butter Box Lid, Norco Co-Op Ltd","object_type":"Boxes","dublin_core":"Physical Object","brief_description":"Piece of plywood stamped ''Norco Co-Op Limited. From a Norco butter box.","web_public_description":"Piece of plywood stamped ''Norco Co-Op Limited. From a Norco butter box.","location":"Verandah","location_notes":"Was in the Orrigo Butter box.","location_history":"Verandah","location_history_date":"16/06/2023","location_history_notes":"Dairy display","comments":"DDM_M1089-col.dng\nDDM_M1089-col.tif\nDDM_M1089-d01.dng\nDDM_M1089-d01.tif\nDDM_M1089-d02.dng\nDDM_M1089-d02.tif\nDDM_M1089.md5","comments_date":"15/08/2023","comments_person":"A Long","general_flag_admin":"Digitised"}', 'secondreport_xml_7f337cc921094b62b3bdd0725e70ec7c.xml');
INSERT INTO ehive_records (object_record_id, object_number, name, object_type, place_made, maker, location, perspective, public_access, fields_json, source_file) VALUES ('1831714', 'M1227', 'Log Calculator', 'Calculators', NULL, NULL, 'Main, western wall', 'HISTORY', 0, '{"object_number":"M1227","name":"Log Calculator","object_type":"Calculators","dublin_core":"Physical Object","brief_description":"Armstrong Rapid Log Calculator comprising two wooden rollers with printed numbers within plastic covers, and sitting in a purpose made wooden stand. The calculator is effectively a cylindrical slide rule. \n\nUsed by Forestry Corporation of NSW staff at their Dorrigo Office.","web_public_description":"Armstrong Rapid Log Calculator comprising two wooden rollers with printed numbers within plastic covers, and sitting in a purpose made wooden stand. The calculator is effectively a cylindrical slide rule. \n\nUsed by Forestry Corporation of NSW staff at their Dorrigo Office.","location":"Main, western wall","location_history":"Main, western wall","location_history_date":"15/06/2023","location_history_notes":"Open shelf","medium_description":"Wood, metal, plastic","inscription":"Metal printed label attached to right side ''ARMSTRONG/ RADID/ LOG CALCULATOR''","measurement_description":"120mm H, 360mm L, 210mm W","association_keyword":"Timber","catalogued_date":"15/06/2023","general_notes_acquisition":"Donated by:\nForestry Corporation, Dorrigo Office","credit_line":"Donor: Forestry Corporation, Dorrigo Office","comments":"DDM_M1227-d01.dng\nDDM_M1227-d01.tif\nDDM_M1227-d02.dng\nDDM_M1227-d02.tif\nDDM_M1227-d03.dng\nDDM_M1227-d03.tif\nDDM_M1227-d04.dng\nDDM_M1227-d04.tif\nDDM_M1227-d05.dng\nDDM_M1227-d05.tif\nDDM_M1227-d06.dng\nDDM_M1227-d06.tif\nDDM_M1227.md5","comments_date":"28/08/2023","comments_person":"A Long","general_flag_admin":"Digitised","current_condition_description":"Fair, well used, print on rollers is fading."}', 'secondreport_xml_7f337cc921094b62b3bdd0725e70ec7c.xml');
INSERT INTO ehive_records (object_record_id, object_number, name, object_type, place_made, maker, location, perspective, public_access, fields_json, source_file) VALUES ('838375', 'M1313', 'Harriet Nutt''s Lawn Bowls Dress', NULL, 'Dorrigo', NULL, NULL, 'HISTORY', 0, '{"object_number":"M1313","name":"Harriet Nutt''s Lawn Bowls Dress","dublin_core":"Physical Object","brief_description":"This white rayon, waisted bowls dress, features a semi-fitted bodice and a full skirt, pleated from the waist to the hip line.  It has a lined white lace collar, three white milk buttons down the front of the bodice and a white rayon fabric belt with a white plastic buckle.  It is ‘home-made’ partly by machine and partly by hand. \n\nThe dress is believed to have been made by Harriet Nutt (née Jackson) [1885-1968] and worn by her when she played Lawn Bowls at the Dorrigo Bowling Club during the 1950s and early 1960s.  Harriet moved to a farm in the Fernbrook area west of Dorrigo, following her marriage to William Nutt [1886- 1921] in 1917, but after her husband’s untimely death in 1921, she moved to the Dorrigo township with her two young sons where she owned and operated a mixed business for more than 16 years. During this time she was an active member of various community organisations, including the Anglican Church and the Red Cross. \n\nAlthough women have been playing bowls in most countries throughout the world for almost as long as men, the participation of women in the game in Australia was first recorded in a tournament at Stawell in Victoria in October 1881.  In 1907, the Victorian Ladies’ Bowling Association was formed and it is believed to be the oldest women’s bowling association in the world.  Other women’s associations were formed around Australia in NSW in 1929, in Queensland in 1930, in South Australia in 1930, in Western Australia in 1935, in Tasmania in 1936 and in the Northern Territory in 1983.\n  \nWomen started playing bowls at the Dorrigo Bowling Club in 1948, and Harriet commenced playing there in 1951.  From 1952 until 1958 she was Vice President of the Ladies’ Committee, and she was made Patroness and a Life Member in 1964.  During that period, women were required to wear a plain white uniform, together with white stockings, white shoes and a white hat; hence they were often referred to by the nickname “White Leghorns.”  Over the years the uniform has gradually changed with dresses giving way to shirts and trousers, and ‘whites’ giving way to colours.\n\nIn the 1950s many sewing materials were in short supply, so often families had to ‘make do’ with whatever materials were available.  Similarly it was usually only the more wealthy families who were able to afford ready-made or professionally-made garments.  This bowls dress demonstrates that the maker was a capable seamstress and that she also had access, and funds, to purchase good quality fabric as well as buttons and notions.  It appears that Mrs Nutt may have worn the dress throughout the 15 years of her association with the Dorrigo Bowling Club, so its current good condition confirms both her competent workmanship and the quality materials used.  \n\nWomen’s bowling clubs now have a membership of more than 160,000 throughout Australia and many are owned and operated solely by women, but sadly, the Dorrigo Club ceased to function in 2011 due to the lack of players.  This dress therefore is a reminder not only of a time when an all-white uniform was a requirement for all women bowlers, but also of a recreational pastime which although once providing much friendship and pleasure for the women of the Dorrigo plateau, has been superseded by other types of activities which have more appeal to the current residents of the area.\n\nPam Cork and Margaret Blight \n7 October 2017","web_public_description":"This white rayon, waisted bowls dress, features a semi-fitted bodice and a full skirt, pleated from the waist to the hip line.  It has a lined white lace collar, three white milk buttons down the front of the bodice and a white rayon fabric belt with a white plastic buckle.  It is ‘home-made’ partly by machine and partly by hand. \n\nThe dress is believed to have been made by Harriet Nutt (née Jackson) [1885-1968] and worn by her when she played Lawn Bowls at the Dorrigo Bowling Club during the 1950s and early 1960s.  Harriet moved to a farm in the Fernbrook area west of Dorrigo, following her marriage to William Nutt [1886- 1921] in 1917, but after her husband’s untimely death in 1921, she moved to the Dorrigo township with her two young sons where she owned and operated a mixed business for more than 16 years. During this time she was an active member of various community organisations, including the Anglican Church and the Red Cross. \n\nAlthough women have been playing bowls in most countries throughout the world for almost as long as men, the participation of women in the game in Australia was first recorded in a tournament at Stawell in Victoria in October 1881.  In 1907, the Victorian Ladies’ Bowling Association was formed and it is believed to be the oldest women’s bowling association in the world.  Other women’s associations were formed around Australia in NSW in 1929, in Queensland in 1930, in South Australia in 1930, in Western Australia in 1935, in Tasmania in 1936 and in the Northern Territory in 1983.\n  \nWomen started playing bowls at the Dorrigo Bowling Club in 1948, and Harriet commenced playing there in 1951.  From 1952 until 1958 she was Vice President of the Ladies’ Committee, and she was made Patroness and a Life Member in 1964.  During that period, women were required to wear a plain white uniform, together with white stockings, white shoes and a white hat; hence they were often referred to by the nickname “White Leghorns.”  Over the years the uniform has gradually changed with dresses giving way to shirts and trousers, and ‘whites’ giving way to colours.\n\nIn the 1950s many sewing materials were in short supply, so often families had to ‘make do’ with whatever materials were available.  Similarly it was usually only the more wealthy families who were able to afford ready-made or professionally-made garments.  This bowls dress demonstrates that the maker was a capable seamstress and that she also had access, and funds, to purchase good quality fabric as well as buttons and notions.  It appears that Mrs Nutt may have worn the dress throughout the 15 years of her association with the Dorrigo Bowling Club, so its current good condition confirms both her competent workmanship and the quality materials used.  \n\nWomen’s bowling clubs now have a membership of more than 160,000 throughout Australia and many are owned and operated solely by women, but sadly, the Dorrigo Club ceased to function in 2011 due to the lack of players.  This dress therefore is a reminder not only of a time when an all-white uniform was a requirement for all women bowlers, but also of a recreational pastime which although once providing much friendship and pleasure for the women of the Dorrigo plateau, has been superseded by other types of activities which have more appeal to the current residents of the area.\n\nPam Cork and Margaret Blight \n7 October 2017","date_made":"1950s","place_made":"Dorrigo","medium_description":"Cotton, plastic","credit_line":"Donor: Mrs M Byrne"}', 'secondreport_xml_7f337cc921094b62b3bdd0725e70ec7c.xml');
INSERT INTO ehive_records (object_record_id, object_number, name, object_type, place_made, maker, location, perspective, public_access, fields_json, source_file) VALUES ('1831716', 'M1353', 'Trophy Jug, Newcastle A H & I Association', 'Jugs', 'Victoria', 'Crusader Plate Co Pty Ltd', 'Main, East Wall, Mid Section', 'HISTORY', 0, '{"object_number":"M1353","name":"Trophy Jug, Newcastle A H & I Association","object_type":"Jugs","dublin_core":"Physical Object","brief_description":"Silver plate jug on a small pedestal base and curved handle with straining bar near the small pouring lip. There is an embossed grape and vine pattern around the upper part. Engraved on one side \"NEWCASTLE A H & I ASSOCIATION/ 1969 SHOW/ P. & O. LINES OF AUSTRALIA PTY. LTD./ FOR/ HIGHEST AGGREGATE IN CLASSES/ 1.2.3. BUTTER SECTION WON BY/ DORRIGO DAIRY CO. LTD./ DORRIGO'' \n\nThe first Dorrigo Butter Factory opened in 1906.","web_public_description":"Silver plate jug on a small pedestal base and curved handle with straining bar near the small pouring lip. There is an embossed grape and vine pattern around the upper part. Engraved on one side \"NEWCASTLE A H & I ASSOCIATION/ 1969 SHOW/ P. & O. LINES OF AUSTRALIA PTY. LTD./ FOR/ HIGHEST AGGREGATE IN CLASSES/ 1.2.3. BUTTER SECTION WON BY/ DORRIGO DAIRY CO. LTD./ DORRIGO'' \n\nThe first Dorrigo Butter Factory opened in 1906.","primary_creator_maker":"Crusader Plate Co Pty Ltd","primary_creator_maker_role":"Manufacturer","date_made":"c1969","place_made":"Victoria","place_notes":"Abbotsford","location":"Main, East Wall, Mid Section","location_history":"Main, East Wall, Mid Section","location_history_date":"15/06/2023","location_history_notes":"On tip of piano","medium_description":"Metal","inscription":"Stamped on base ''Crusader/ PLATE/ E.P.N.S.A.1''","measurement_description":"150mm H, 165mmW, 110mm Deep","association_keyword":"Agriculture","general_notes_object":"References:\nhttps://collection.powerhouse.com.au/object/340058, accessed o n15/06/2023","catalogued_date":"15/06/2023","comments":"DDM_M1353-d01.dng\nDDM_M1353-d01.tif\nDDM_M1353-d02.dng\nDDM_M1353-d02.tif\nDDM_M1353-d03.dng\nDDM_M1353-d03.tif\nDDM_M1353-d04.dng\nDDM_M1353-d04.tif\nDDM_M1353.md5","comments_date":"28/08/2023","comments_person":"A Long","general_flag_admin":"Digitised","current_condition_description":"Good, some tarnish."}', 'secondreport_xml_7f337cc921094b62b3bdd0725e70ec7c.xml');
INSERT INTO ehive_records (object_record_id, object_number, name, object_type, place_made, maker, location, perspective, public_access, fields_json, source_file) VALUES ('1657926', 'M1502a', 'Handkerchief', 'Handkerchiefs', NULL, 'Leonardo Parente', NULL, 'HISTORY', 0, '{"object_number":"M1502a","accession_date":"c2015","name":"Handkerchief","object_type":"Handkerchiefs","dublin_core":"Physical Object","brief_description":"Hand painted handkerchief created by Prisoner of War (POW) Leonardo Parente (b1920), Australian POW No. 46380 (British POW No. 111179). Parente was born in S. Severo Foggia, Italy and was a Corporal in the Italian Army at the time of his capture on 04 January 1941 in Libya. He was transported to Australia on the Queen Mary and arrived at the Hay Prisoner of War Camp in July 1941. \n\nLeonardo Parente spent time in a number of POW camps in NSW and in October 1943 was moved to the POW North Coast Control Centre at Dorrigo where he was assigned to work on George Winkley''s farm on the Fernbrook Road. \n\nPainted on the handkerchief is a ship at sea in the foreground, and a simple map depicting  the route from Italy to North Africa and after Leonardo’s capture as a Prisoner of War from Libya to Australia  The handkerchief also includes text printed in black ink: ''TO JEAN FROM PARENTE -L P.O.W./ FOR KEEPSAKE 9-11-45/ DORRIGO''. Painted in each corner of the handkerchief are floral motifs.","web_public_description":"Hand painted handkerchief created by Prisoner of War (POW) Leonardo Parente (b1920), Australian POW No. 46380 (British POW No. 111179). Parente was born in S. Severo Foggia, Italy and was a Corporal in the Italian Army at the time of his capture on 04 January 1941 in Libya. He was transported to Australia on the Queen Mary and arrived at the Hay Prisoner of War Camp in July 1941. \n\nLeonardo Parente spent time in a number of POW camps in NSW and in October 1943 was moved to the POW North Coast Control Centre at Dorrigo where he was assigned to work on George Winkley''s farm on the Fernbrook Road. \n\nPainted on the handkerchief is a ship at sea, and a simple map depicting  the route from Italy to North Africa and after Leonardo’s capture as a Prisoner of War from Libya to Australia. The handkerchief also includes text printed in black ink: ''TO JEAN FROM PARENTE -L P.O.W./ FOR KEEPSAKE 9-11-45/ DORRIGO''. Painted in each corner of the handkerchief are floral motifs.","primary_creator_maker":"Leonardo Parente","date_made":"c1945","medium_description":"Textile, paint, ink","association_keyword":"Wars","general_notes_object":"Created by D Sommers from an object assessment compiled by Libby Newell dated 26 July 2017\n\nOther references:\nPOW records for Leonardo Parente - naa.gov.au, accessed on 12/03/2023\nhttps://en.wikipedia.org/w/index.php?title=Italian_prisoners_of_war_in_Australia&oldid=1138698889, accessed on 12/03/2023","credit_line":"Donor: J Winkley, 2015","current_condition_description":"Handkerchief is currently framed. Condition has not been assessed."}', 'secondreport_xml_7f337cc921094b62b3bdd0725e70ec7c.xml');
INSERT INTO ehive_records (object_record_id, object_number, name, object_type, place_made, maker, location, perspective, public_access, fields_json, source_file) VALUES ('1755256', 'M1514', 'Trophy, NSW Junior Farmers', 'Trophies', NULL, 'Ranleigh', 'Washstand bottom shelf', 'HISTORY', 0, '{"object_number":"M1514","accession_date":"March 2012","name":"Trophy, NSW Junior Farmers","object_type":"Trophies","dublin_core":"Physical Object","brief_description":"Rectangular metal tray with side handles and railing edges. Tray surface has a circular patterning, and is set on a Masonite base, sitting on four short rubber feet. Awarded to Arnold Whittaker, Dorrigo Junior Farmers Club, for potato growing, at the NSW Junior Farmers State Championships in 1949. The Bank of NSW sponsored the trophy.","web_public_description":"Rectangular metal tray with side handles and railing edges. Tray surface has a circular patterning, and is set on a Masonite base, sitting on four short rubber feet. Awarded to Arnold Whittaker, Dorrigo Junior Farmers Club, for potato growing,  at the NSW Junior Farmers State Championships in 1949. The Bank of NSW sponsored the trophy.","primary_creator_maker":"Ranleigh","primary_creator_maker_role":"Manufacturer","date_made":"c1949","location":"Washstand bottom shelf","location_history":"Washstand bottom shelf","location_history_date":"16/6/2023","medium_description":"Metal, Masonite, rubber","inscription":"Stamped on upper right ''RANLEIGH''.  \nEngraved in centre ''NSW JUNIOR FARMERS 1949 STATE CHAMPIONSHIP/POTATO GROWING/(COSTAL [sic] DIVISION/BANK OF NSW TROPHY/WON BY/ARNOLD WHITTAKER/DORRIGO CLUB''.","measurement_description":"445mm L, 280mm W","association_keyword":"Agriculture","catalogued_date":"16/06/2023","cataloguer":"Robyn Cork","general_notes_acquisition":"Donated by: Trudy Whittaker (daughter)\nMarch 2012","credit_line":"Donor: T Whittaker, 2012","comments":"DDM_M1514-col.dng\nDDM_M1514-col.tif\nDDM_M1514-d01.dng\nDDM_M1514-d01.tif\nDDM_M1514-d02.dng\nDDM_M1514-d02.tif\nDDM_M1514-d03.dng\nDDM_M1514-d03.tif\nDDM_M1514-d04.dng\nDDM_M1514-d04.tif\nDDM_M1514-d05.dng\nDDM_M1514-d05.tif\nDDM_M1514.md5","comments_date":"17/08/2023","comments_person":"A Long","general_flag_admin":"Digitised","current_condition_description":"Fair. Some scratches and tarnish to upper surface."}', 'secondreport_xml_7f337cc921094b62b3bdd0725e70ec7c.xml');
INSERT INTO ehive_records (object_record_id, object_number, name, object_type, place_made, maker, location, perspective, public_access, fields_json, source_file) VALUES ('1755439', 'M1579', 'Needlework Sampler', 'Textile samplers', NULL, 'Venetta Glossop', 'Bedroom', 'HISTORY', 0, '{"object_number":"M1579","accession_date":"1981","name":"Needlework Sampler","object_type":"Textile samplers","dublin_core":"Physical Object","brief_description":"Small square sampler worked in various embroidery stitches and demonstrating cutwork, mending, button holes and stitched loops.  The maker''s name ''Venetta Glossop'' and date ''1898'' are embroidered at the lower edge in chain stitch.  The sampler has been framed in an ornate gold metal frame.\n\nIn 1922, Venetta Glossop won a number of the prizes in the Women''s Industries exhibition at the Royal Brisbane Show, including first prizes for a specimen of machine sewing, and art embroidery in heavy silk. Venetta Lucy Glossop, died 1942.","web_public_description":"Small square sampler worked in various embroidery stitches and demonstrating cutwork, mending, button holes and stitched loops.  The maker''s name ''Venetta Glossop'' and date ''1898'' are embroidered at the lower edge in chain stitch. The sampler has been framed in an ornate gold metal frame.\n\nIn 1922, Venetta Glossop won a number of the prizes in the Women''s Industries exhibition at the Royal Brisbane Show, including first prizes for a specimen of machine sewing, and art embroidery in heavy silk. Venetta Lucy Glossop, died 1942.","primary_creator_maker":"Venetta Glossop","date_made":"1898","location":"Bedroom","location_history":"Bedroom","location_history_date":"15/06/2023","location_history_notes":"Hanging from bed head.","medium_description":"Textile, metal, glass","inscription":"Embroidered ''Venetta Glossop/1898''","measurement_description":"Frame: 250mm L, 225mm W\nSampler:  170mm L, 155mm W","association_keyword":"Schools","general_notes_object":"References:\nVenetta Lucy Glossop died 1942. NSW BDM Death 1197/1942\nFather:  John Beroni\nMother:  Sarah Ann\n\nThe Telegraph (Brisbane), 9 August 1922 - p4 - Royal Show - \nWomen''s Industries","catalogued_date":"21/06/2023","cataloguer":"Robyn Cork","general_notes_acquisition":"Donated by: \nMrs Marion McCourt","credit_line":"Donor: M McCourt, 1981","comments":"DDM_M1579-col.dng\nDDM_M1579-col.tif\nDDM_M1579-p001.dng\nDDM_M1579-p001.tif\nDDM_M1579-p002.dng\nDDM_M1579-p002.tif\nDDM_M1579.md5","comments_date":"28/08/2023","comments_person":"A Long","general_flag_admin":"Digitised","current_condition_description":"Fair, stained.  Not removed from frame for examination."}', 'secondreport_xml_7f337cc921094b62b3bdd0725e70ec7c.xml');
INSERT INTO ehive_records (object_record_id, object_number, name, object_type, place_made, maker, location, perspective, public_access, fields_json, source_file) VALUES ('1831712', 'M1584', 'Souvenir Ashtray, Dorrigo', 'Ashtrays', 'Melbourne', 'Stokes and Sons', 'Main, East Wall, Mid Section', 'HISTORY', 0, '{"object_number":"M1584","name":"Souvenir Ashtray, Dorrigo","object_type":"Ashtrays","dublin_core":"Physical Object","brief_description":"Circular pressed metal souvenir ashtray with fluted edges and textured surface. In the centre is a coloured circular enamel disc featuring motifs representing a log truck, trees, mountains and text ''DORRIGO''. Around the centre disc are embossed pictures of koalas, a kookaburra and a kangaroo.","web_public_description":"Circular pressed metal souvenir ashtray with fluted edges and textured surface. In the centre is a coloured circular enamel disc featuring motifs representing a log truck, trees, mountains and text ''DORRIGO''. Around the centre disc are embossed pictures of koalas, a kookaburra and a kangaroo.","primary_creator_maker":"Stokes and Sons","primary_creator_maker_role":"Manufacturer","place_made":"Melbourne","location":"Main, East Wall, Mid Section","location_history":"Main, East Wall, Mid Section","location_history_date":"15/06/2023","location_history_notes":"On washstand","medium_description":"Metal, enamel","inscription":"Impressed on base '' STOKES MELB.''","measurement_description":"15mm H, 125mm Diameter","association_keyword":"Tourism","catalogued_date":"15/06/2023","comments":"DDM_M1584-col.dng\nDDM_M1584-col.tif\nDDM_M1584-d01.dng\nDDM_M1584-d01.tif\nDDM_M1584-d02.dng\nDDM_M1584-d02.tif\nDDM_M1584.md5","comments_date":"28/08/2023","comments_person":"A Long","general_flag_admin":"Digitised","current_condition_description":"Good, some small marks visible in metal."}', 'secondreport_xml_7f337cc921094b62b3bdd0725e70ec7c.xml');
INSERT INTO ehive_records (object_record_id, object_number, name, object_type, place_made, maker, location, perspective, public_access, fields_json, source_file) VALUES ('1654528', 'M1595', 'Souvenir Plate, Walmsley''s Lookout Dorrigo', 'Plates', 'Czechoslovakia', 'Schmidt & Co.', 'Main, East Wall, Mid Section', 'HISTORY', 0, '{"object_number":"M1595","accession_date":"--/07/2015","name":"Souvenir Plate, Walmsley''s Lookout Dorrigo","object_type":"Plates","dublin_core":"Physical Object","brief_description":"Circular white glazed petal shaped souvenir plate with fluted gold edging. The plate features a colour transfer picture of a landscape scene viewed from  Walmsley Lookout showing mountains in the distance and trees and green foliage in the foreground. Below the picture is text printed in black ''WALMSLEY''S LOOKOUT, DORRIGO, N.S.W.'' \n\nThe area now known as Dorrigo lies on the traditional land of the Gumbaynggirr people.  Timber cutters entered the Bellinger River valley from 1841 searching for red cedar, and permanent European settlement followed from the 1860s. It is however Dorrigo’s unrivalled natural environment and scenic beauty that sets it apart from any other place on the Mid North Coast and beyond.  \n\nAn article by Miss Violet Roche published in 1930 describes Dorrigo’s majestic splendour “… Amid the rich scenic loveliness of the North Coast, Dorrigo is preeminent for the magnificence of its mountain, valley and forest beauty. Enchantment captures the visitor… The rust red soil and emerald pastures, undulates prettily and is watered by many streams… \n\nOf the lookout points on the plateau, Walmsley’s Lookout and Major’s Lookout are outstanding. Range after range of soft, mist-blue mountains stretch as far as the eye can see to the sky-line where a vivid line of blue with a border of white marks the surf fringed ocean. Immediately below is a verdant river valley - a scene of peaceful serenity…”","web_public_description":"Circular white glazed petal shaped souvenir plate with fluted gold edging. The plate features a colour transfer picture of a landscape scene viewed from  Walmsley Lookout showing mountains in the distance and trees and green foliage in the foreground. Below the picture is text printed in black ''WALMSLEY''S LOOKOUT, DORRIGO, N.S.W.'' \n\nThe area now known as Dorrigo lies on the traditional land of the Gumbaynggirr people.  Timber cutters entered the Bellinger River valley from 1841 searching for red cedar, and permanent European settlement followed from the 1860s. It is however Dorrigo’s unrivalled natural environment and scenic beauty that sets it apart from any other place on the Mid North Coast and beyond.  \n\nAn article by Miss Violet Roche published in 1930 describes Dorrigo’s majestic splendour “… Amid the rich scenic loveliness of the North Coast, Dorrigo is preeminent for the magnificence of its mountain, valley and forest beauty. Enchantment captures the visitor… The rust red soil and emerald pastures, undulates prettily and is watered by many streams… \n\nOf the lookout points on the plateau, Walmsley’s Lookout and Major’s Lookout are outstanding. Range after range of soft, mist-blue mountains stretch as far as the eye can see to the sky-line where a vivid line of blue with a border of white marks the surf fringed ocean. Immediately below is a verdant river valley - a scene of peaceful serenity…”","primary_creator_maker":"Schmidt & Co.","primary_creator_maker_role":"Manufacturer","date_made":"c1930","place_made":"Czechoslovakia","location":"Main, East Wall, Mid Section","location_history":"Main, East Wall, Mid Section","location_history_date":"01/03/2023","location_history_notes":"Cabinet, Bottom Shelf","medium_description":"Ceramic","inscription":"Printed on base in green ink ''[crown]/VICTORIA/Czechoslovakia''.\nPrinted on base in gold ink ''258''.","measurement_description":"31mm H, 127mm diam, base 77mm diam.","association_keyword":"Tourism","general_notes_object":"References:\nPlating Up History: The Story of Australian Souvenir China, G Poliness, Australian eBook Publisher, 2015","catalogued_date":"01/03/2023","cataloguer":"Kate Smith","general_notes_acquisition":"Donated by: Shirley Moran, Cypress St Dorrigo.","credit_line":"Donor: S Moran, 2015","comments":"DDM_M1595-col.dng\nDDM_M1595-col.tif\nDDM_M1595-d01.dng\nDDM_M1595-d01.tif\nDDM_M1595-d02.dng\nDDM_M1595-d02.tif\nDDM_M1595.md5","comments_date":"28/08/2023","comments_person":"A Long","general_flag_admin":"Digitised","current_condition_description":"Very good, appears unused."}', 'secondreport_xml_7f337cc921094b62b3bdd0725e70ec7c.xml');
INSERT INTO ehive_records (object_record_id, object_number, name, object_type, place_made, maker, location, perspective, public_access, fields_json, source_file) VALUES ('1831715', 'M1651', 'Blazer, Dorrigo Rugby Football League', 'Jackets', NULL, NULL, 'Bedroom', 'HISTORY', 0, '{"object_number":"M1651","name":"Blazer, Dorrigo Rugby Football League","object_type":"Jackets","dublin_core":"Physical Object","brief_description":"Men''s black woolen blazer with braid trim at chest pocket, patch pockets and lower sleeves. The chest pocket is embroidered ''D.R.F.L.'' above a rising sun emblem with a coat of arms and further text ''DORRIGO CUP TEAM''. The blazer is single breasted and lined with striped cotton fabric. \n\nWorn by Raymond Charles Cork (known as Fred) [d.2002].","web_public_description":"Men''s black woolen blazer with braid trim at chest pocket, patch pockets and lower sleeves. The chest pocket is embroidered ''D.R.F.L.'' above a rising sun emblem with a coat of arms and further text ''DORRIGO CUP TEAM''. The blazer is single breasted and lined with striped cotton fabric. \n\nWorn by Raymond Charles Cork (known as Fred) [d.2002].","location":"Bedroom","location_history":"Bedroom","location_history_date":"15/06/2023","location_history_notes":"Hanging on wall","medium_description":"Textiles, plastic","association_keyword":"Football","catalogued_date":"15/06/2023","comments":"DDM_M1651-d01.dng\nDDM_M1651-d01.tif\nDDM_M1651-d02.dng\nDDM_M1651-d02.tif\nDDM_M1651.md5","comments_date":"17/08/2023","comments_person":"A Long","general_flag_admin":"Digitised","current_condition_description":"Good. Some small insect holes on front. Back not yet examined."}', 'secondreport_xml_7f337cc921094b62b3bdd0725e70ec7c.xml');
INSERT INTO ehive_records (object_record_id, object_number, name, object_type, place_made, maker, location, perspective, public_access, fields_json, source_file) VALUES ('1755398', 'M1652', 'Butter Dish, Bellingen Show', 'Dishes', 'Czechoslovakia', 'Victoria Czechoslovakia - Schmidt & Co', 'Main, East Wall, Mid Section', 'HISTORY', 0, '{"object_number":"M1652","name":"Butter Dish, Bellingen Show","object_type":"Dishes","dublin_core":"Physical Object","brief_description":"White china bowl with decorative cut-out border and gilt rim. Around the sides are transfer prints of flowers, including violets and roses and in the centre of the base is a transfer picture of the Bellingen Showground with text below, ''BELLINGEN SHOW 1930''.","web_public_description":"White china bowl with decorative cut-out border and gilt rim. Around the sides are transfer prints of flowers, including violets and roses and in the centre of the base is a transfer picture of the Bellingen Showground with text below, ''BELLINGEN SHOW 1930''.","primary_creator_maker":"Victoria Czechoslovakia - Schmidt & Co","date_made":"1930","place_made":"Czechoslovakia","location":"Main, East Wall, Mid Section","location_history":"Main, East Wall, Mid Section","location_history_date":"15/06/2023","location_history_notes":"On washstand","medium_description":"Ceramic, ink","inscription":"Stamped on base:  ''[CROWN]/VICTORIA/CHINA/CZECHOSLOVAKIA''","measurement_description":"33mm H, 135mm Diameter","association_keyword":"Agriculture","catalogued_date":"21/06/2023","cataloguer":"Robyn Cork","comments":"DDM_M1652-col.dng\nDDM_M1652-col.tif\nDDM_M1652-d01.dng\nDDM_M1652-d01.tif\nDDM_M1652-d02.dng\nDDM_M1652-d02.tif\nDDM_M1652.md5\nPMM_M1652.md5","comments_date":"28/08/2023","comments_person":"A Long","general_flag_admin":"Digitised","current_condition_description":"Good."}', 'secondreport_xml_7f337cc921094b62b3bdd0725e70ec7c.xml');
INSERT INTO ehive_records (object_record_id, object_number, name, object_type, place_made, maker, location, perspective, public_access, fields_json, source_file) VALUES ('1831713', 'M1665', 'Embroidered Apron, ''Two Little Girls in Blue''', 'Aprons', 'Dorrigo', NULL, 'Kitchen Display', 'HISTORY', 0, '{"object_number":"M1665","accession_date":"--/09/2017","name":"Embroidered Apron, ''Two Little Girls in Blue''","object_type":"Aprons","dublin_core":"Physical Object","brief_description":"Women''s calico bib apron with pale blue binding around edges forming neck loop and waist ties. Embroidered on the lower section in blue thread are two women holding hands and wearing long dresses, capes and bonnets. A patch pocket on the left hip is also bound pale blue fabric/binding, and has embroidered text ''Two little Girls in Blue''. \n\nWorked by Elizabeth Harrison''s grandmother Annie Harrison of Karabin Steet, Dorrigo","web_public_description":"Women''s calico bib apron with pale blue binding around edges forming neck loop and waist ties. Embroidered on the lower section in blue thread are two women holding hands and wearing long dresses, capes and bonnets. A patch pocket on the left hip is also bound pale blue fabric/binding, and has embroidered text ''Two little Girls in Blue''. \n\nWorked by Elizabeth Harrison''s grandmother Annie Harrison of Karabin Steet, Dorrigo","place_made":"Dorrigo","location":"Kitchen Display","location_history":"Kitchen Display","location_history_date":"15/06/2023","location_history_notes":"On mannequin","medium_description":"Textilles","measurement_description":"750mm L (excluding neck loop), 550mm W","association_keyword":"Crafts","catalogued_date":"15/06/2023","general_notes_acquisition":"Donated by:\nElizabeth Harrison","credit_line":"Donor: E Harrison, 2017","comments":"DDM_M1665-d01.dng\nDDM_M1665-d01.tif\nDDM_M1665-d02.dng\nDDM_M1665-d02.tif\nDDM_M1665.md5","comments_date":"28/08/20232","comments_person":"A Long","general_flag_admin":"Digitised","current_condition_description":"Fair. Well worn."}', 'secondreport_xml_7f337cc921094b62b3bdd0725e70ec7c.xml');
INSERT INTO ehive_records (object_record_id, object_number, name, object_type, place_made, maker, location, perspective, public_access, fields_json, source_file) VALUES ('1831717', 'M1668', 'Milk Jug, Hotel Dorrigo', 'Jugs', NULL, 'Challenge Silverware', 'Main, East Wall, Mid Section', 'HISTORY', 0, '{"object_number":"M1668","accession_date":"16/01/2019","name":"Milk Jug, Hotel Dorrigo","object_type":"Jugs","dublin_core":"Physical Object","brief_description":"Silver plate milk jug with hinged lid and shaped handle. The handle features the distinctive design of Challenge Silverware, which was owned by the Robur Tea Company. On one side is stamped text ''HOTEL DORRIGO''. \n\nThe Dorrigo Hotel opened in 1925.","web_public_description":"Silver plate milk jug with hinged lid and shaped handle. The handle features the distinctive design of Challenge Silverware, which was owned by the Robur Tea Company. On one side is stamped text ''HOTEL DORRIGO''. \n\nThe Dorrigo Hotel opened in 1925.","primary_creator_maker":"Challenge Silverware","primary_creator_maker_role":"Manufacturer","date_made":"1920s","location":"Main, East Wall, Mid Section","location_history":"Main, East Wall, Mid Section","location_history_date":"15/06/2023","location_history_notes":"On washstand","medium_description":"Metal","inscription":"Stamped on base ''CHALLENGE EPNS/ A1/ WARRANTED/ HARD/ SILVER SOLDERED, 363''","measurement_description":"140mm H, 140mm W, 80mm Diameter at base","association_keyword":"Hotels","general_notes_object":"References:\nhttps://collection.powerhouse.com.au/object/11636, accessed on 15/06/2023","catalogued_date":"15/06/2023","general_notes_acquisition":"Donated by:\nBernie Gilbert","credit_line":"Donor: B Gilbert, 2019","comments":"DDM_M1668-d01.dng\nDDM_M1668-d01.tif\nDDM_M1668-d02.dng\nDDM_M1668-d02.tif\nDDM_M1668-d03.dng\nDDM_M1668-d03.tif\nDDM_M1668-d04.dng\nDDM_M1668-d04.tif\nDDM_M1668.md5","comments_date":"28/08/2023","comments_person":"A Long","general_flag_admin":"Digitised","current_condition_description":"Fair, tarnish and pitting throughout, loss of silver plate on base"}', 'secondreport_xml_7f337cc921094b62b3bdd0725e70ec7c.xml');
INSERT INTO ehive_records (object_record_id, object_number, name, object_type, place_made, maker, location, perspective, public_access, fields_json, source_file) VALUES ('1664052', 'M1686', 'Cup and Saucer, Dangar Falls Dorrigo', 'Cups and Saucers', 'England', 'Chapmans Longton Ltd.', 'Main, East Wall, Mid Section', 'HISTORY', 0, '{"object_number":"M1686","name":"Cup and Saucer, Dangar Falls Dorrigo","object_type":"Cups and Saucers","dublin_core":"Physical Object","brief_description":"White fine bone china souvenir cup and saucer set. Both pieces feature a transfer colour picture in green, brown and light blue tones with brown text ''DANGAR FALLS, DORRIGO, NSW''. The saucer is petal shaped with fluted gilt edging and the cup has gilt around the rim and on the handle.  The cup sits on a small pedestal base.","web_public_description":"White fine bone china souvenir cup and saucer set. Both pieces feature a transfer colour picture in green, brown and light blue tones with brown text ''DANGAR FALLS, DORRIGO, NSW''. The saucer is petal shaped with fluted gilt edging and the cup has gilt around the rim and on the handle.  The cup sits on a small pedestal base.","primary_creator_maker":"Chapmans Longton Ltd.","primary_creator_maker_role":"Potter","date_made":"c1950","place_made":"England","place_notes":"Albert Works, Longton, Stoke-on-Trent","location":"Main, East Wall, Mid Section","location_history":"Main, East Wall, Mid Section","location_history_date":"20/03/2023","location_history_notes":"Wash Stand","medium_description":"Ceramic, ink","inscription":"On base ''[Crown]/Royal Standard/Fine Bone Chine/England. \"Made expressly for Wm Blackley Dorrigo. N.S.W. in brown print. \n\nAlso on cup base: ''4bbm'' in black print","measurement_description":"Cup: 65mm H x 87mm Diameter at top, 45mm Diameter at base\nSaucer: 140mm W","association_keyword":"Tourism","general_notes_object":"References:\n\nAnother bakehouse was built behind the shop along side the N. S. W. (Westpac) Bank in Hickory Street. It was operated by Alf and Herb Wright, or the Wright Bros. Then Mr. Bill Blackley who only passed away on 8th June, 1984 aged 88. He was a wonderful business man and liked by all. \"Early Dorrigo\" by Ruby Miller. \n\nHe ran the Eclipse Bakery in North Dorrigo in 1927 (advertisement from DDG 16 December 1927)\n\nMakers Mark 1949-1969 - Plating Up: The Story of Australian Souvenir China - Grania Poliness, 2015","catalogued_date":"20/03/2023","cataloguer":"Kate Smith","comments":"DDM_M1686-col.dng\nDDM_M1686-col.tif\nDDM_M1686-d01.dng\nDDM_M1686-d01.tif\nDDM_M1686-d02.dng\nDDM_M1686-d02.tif\nDDM_M1686-d03.dng\nDDM_M1686-d03.tif\nDDM_M1686-d04.dng\nDDM_M1686-d04.tif\nDDM_M1686-d05.dng\nDDM_M1686-d05.tif\nDDM_M1686-d06.dng\nDDM_M1686-d06.tif\nDDM_M1686.md5","comments_date":"17/08/2023","comments_person":"A Long","general_flag_admin":"Digitised","current_condition_description":"Good."}', 'secondreport_xml_7f337cc921094b62b3bdd0725e70ec7c.xml');
INSERT INTO ehive_records (object_record_id, object_number, name, object_type, place_made, maker, location, perspective, public_access, fields_json, source_file) VALUES ('1831783', 'M1716', 'Post Office Banking Bag', 'Bags', NULL, NULL, NULL, 'HISTORY', 0, '{"object_number":"M1716","name":"Post Office Banking Bag","object_type":"Bags","dublin_core":"Physical Object","brief_description":"Leather bag in a Gladstone style, built over a rigid frame, and opening into two equal sections. The bag has a firm base, and is reinforced with extra strapping on each side forming short handles at the top. There are two sliding locks along the top of the bag''s frame. The bag includes a locking mechanism and has a small brass padlock with key attached. \n\nThis bag was used by Dorrigo Post Office staff to carry cash to and from the bank.","web_public_description":"Leather bag in a Gladstone style, built over a rigid frame, and opening into two equal sections. The bag has a firm base, and is reinforced with extra strapping on each side forming short handles at the top. There are two sliding locks along the top of the bag''s frame. The bag includes a locking mechanism and has a small brass padlock with key attached. \n\nThis bag was used by Dorrigo Post Office staff to carry cash to and from the bank.","general_notes_object":"Note:\nBag not yet examined or measured. There may be Maker''s marks and other distinguishing features.","catalogued_date":"16/06/2023","comments":"DDM_M1716-d01.dng\nDDM_M1716-d01.tif\nDDM_M1716-d02.dng\nDDM_M1716-d02.tif\nDDM_M1716-d03.dng\nDDM_M1716-d03.tif\nDDM_M1716-d04.dng\nDDM_M1716-d04.tif\nDDM_M1716.md5","comments_date":"15/08/2023","comments_person":"A Long","general_flag_admin":"Digitised"}', 'secondreport_xml_7f337cc921094b62b3bdd0725e70ec7c.xml');
INSERT INTO ehive_records (object_record_id, object_number, name, object_type, place_made, maker, location, perspective, public_access, fields_json, source_file) VALUES ('1831721', 'M1717', 'Plaque, Francis'' Lookout Dorrigo', 'Plaques', NULL, NULL, 'Office', 'HISTORY', 0, '{"object_number":"M1717","accession_date":"08/01/2022","name":"Plaque, Francis'' Lookout Dorrigo","object_type":"Plaques","dublin_core":"Physical Object","brief_description":"Beaten copper plaque showing compass bearings from Francis'' Lookout., including Trig Stations and other landmarks viewed from the lookout at 3320 feet. The plaque is attached to a wooden board with a copper backing. \n\nBelieve to be created from a drawing by T. W. Francis of Dorrigo in 1930.","web_public_description":"Beaten copper plaque showing compass bearings from Francis'' Lookout., including Trig Stations and other landmarks viewed from the lookout at 3320 feet. The plaque is attached to a wooden board with a copper backing. \n\nBelieve to be created from a drawing by T. W. Francis of Dorrigo in 1930","location":"Office","location_history":"Office","medium_description":"Metal, wood","measurement_description":"20mm H, 613mm L, 505mm W","association_keyword":"Surveying","cataloguer":"Kate Smith","general_notes_acquisition":"Donated by:\nBellingen Museum, donor unknown.","comments":"DDM_M1717-d01.dng\nDDM_M1717-d01.tif\nDDM_M1717.md5","comments_date":"15/08/2023","comments_person":"A Long","general_flag_admin":"Digitised","current_condition_description":"Fair, surface scratching and tarnish."}', 'secondreport_xml_7f337cc921094b62b3bdd0725e70ec7c.xml');
INSERT INTO ehive_records (object_record_id, object_number, name, object_type, place_made, maker, location, perspective, public_access, fields_json, source_file) VALUES ('1841304', 'M1720', 'Blazer, NSW Rugby Football League', 'Jackets', NULL, NULL, 'Research Room', 'HISTORY', 0, '{"object_number":"M1720","name":"Blazer, NSW Rugby Football League","object_type":"Jackets","dublin_core":"Physical Object","brief_description":"Men''s blue blazer with yellow braid trim on sleeves, and chest and patch pockets. The chest pocket is embroidered ''N.S.W.R.F.L./ [Coat of arms]/ Undefeated Major and Minor Premiers/ 1954/ Dorrigo Reserve Grade''. The jacket has two plastic buttons and is fully lined with cotton. \n\nThe reserve grade team finished the 1954 season as minor premiers with 33 points. The team, skippered by Bruce McGuirk, went on to defeat the Bowraville Reserve Grade side to win the 1954 Southern Zone competition premiership played at Urunga on 12 September by 30 points to 5. The Dorrigo Reserve Grade team created a reserve grade record of being undefeated throughout the season.","web_public_description":"Men''s blue blazer with yellow braid trim on sleeves, and chest and patch pockets. The chest pocket is embroidered ''N.S.W.R.F.L./ [Coat of arms]/ Undefeated Major and Minor Premiers/ 1954/ Dorrigo Reserve Grade''. The jacket has two plastic buttons and is fully lined with cotton. \n\nThe reserve grade team finished the 1954 season as minor premiers with 33 points. The team, skippered by Bruce McGuirk, went on to defeat the Bowraville Reserve Grade side to win the 1954 Southern Zone competition premiership played at Urunga on 12 September by 30 points to 5. The Dorrigo Reserve Grade team created a reserve grade record of being undefeated throughout the season.","date_made":"1954","location":"Research Room","location_history":"Research Room","location_history_date":"15/06/2023","location_history_notes":"On mannequin outside room","medium_description":"Textiles, plastic","association_keyword":"Football","general_notes_object":"References:\nDon Dorrigo Gazette, 20 August 1954, p8 \nDon Dorrigo Gazette, 16 September 1954, p8","catalogued_date":"15/06/2023","comments":"DDM_M1273-d01.dng\nDDM_M1273-d01.tif\nDDM_M1273-d02.dng\nDDM_M1273-d02.tif\nDDM_M1273.md5","comments_date":"15/08/2023","comments_person":"A Long","general_flag_admin":"Digitised","current_condition_description":"Good."}', 'secondreport_xml_7f337cc921094b62b3bdd0725e70ec7c.xml');
INSERT INTO ehive_records (object_record_id, object_number, name, object_type, place_made, maker, location, perspective, public_access, fields_json, source_file) VALUES ('1831720', 'M1721', 'Drum', 'Musical instruments', NULL, NULL, 'Main, music section', 'HISTORY', 0, '{"object_number":"M1721","name":"Drum","object_type":"Musical instruments","dublin_core":"Physical Object","brief_description":"Percussion drum used by Les Sawtell''s orchestra throughout the Dorrigo  district during the 1930s. The orchestra comprised many members including Mrs. Wendy Smith, piano; Mr. Les. Sawtell, cornet; and Mr. Jarrett on drums. \n\nAllen Leslie Sawtell, known as Les, was born on 4 December 1897 at Llangothlin, New South Wales.  He died in the Coffs Harbour District Hospital on 8 January 1970.","web_public_description":"Percussion drum used by Les Sawtell''s orchestra throughout the Dorrigo district during the 1930s. The orchestra comprised many members including Mrs. Wendy Smith, piano; Mr. Les. Sawtell, cornet; and Mr. Jarrett on drums.  \n\nAllen Leslie Sawtell, known as Les, was born on 4 December 1897 at Llangothlin, New South Wales.  He died in the Coffs Harbour District Hospital on 8 January 1970.","date_made":"1930s","location":"Main, music section","location_history":"Main, music section","location_history_date":"05/03/2023","measurement_description":"Wood, metal, hide","association_keyword":"Music","general_notes_object":"References:\nhttps://www.facebook.com/1904562406494535/posts/soldiers-letters-from-ww1allen-leslie-sawtell-was-born-on-the-4th-december-1897-/2361176764166428/, accessed on 16/06/2023\n\nDon Dorrigo Gazette, Friday 29 May 1931, p5 - Empire Ball, names some of the band members.","catalogued_date":"05/03/2023","cataloguer":"Robyn Cork","comments":"DDM_M1721-d01.dng\nDDM_M1721-d01.tif\nDDM_M1721-d02.dng\nDDM_M1721-d02.tif\nDDM_M1721-d03.dng\nDDM_M1721-d03.tif\nDDM_M1721.md5","comments_date":"28/08/2023","comments_person":"A Long","general_flag_admin":"Digitised"}', 'secondreport_xml_7f337cc921094b62b3bdd0725e70ec7c.xml');
INSERT INTO ehive_records (object_record_id, object_number, name, object_type, place_made, maker, location, perspective, public_access, fields_json, source_file) VALUES ('1831722', 'M1722', 'Potato Bag Stencil, Washington Bros.', 'Stencils', NULL, NULL, 'Main, western wall', 'HISTORY', 0, '{"object_number":"M1722","name":"Potato Bag Stencil, Washington Bros.","object_type":"Stencils","dublin_core":"Physical Object","brief_description":"Rectangular piece of tin with cut out lettering forming text ''GROWN BY/ WASHINGTON BROS/ NTH DORRIGO N.S.W./ NEW/ POTATOES''","web_public_description":"Rectangular piece of tin with cut out lettering forming text ''GROWN BY/ WASHINGTON BROS/ NTH DORRIGO N.S.W./ NEW/ POTATOES''","location":"Main, western wall","location_history":"Main, western wall","location_history_date":"16/06/2023","location_history_notes":"Under bench","medium_description":"Metal","measurement_description":"555mm L, 510mm W","association_keyword":"Agriculture","catalogued_date":"16/06/2023","comments":"DDM_M1722-d01.dng\nDDM_M1722-d01.tif\nDDM_M1722.md5","comments_date":"28/08/2023","comments_person":"A Long","general_flag_admin":"Digitised","current_condition_description":"Fair, well worn from use."}', 'secondreport_xml_7f337cc921094b62b3bdd0725e70ec7c.xml');
INSERT INTO ehive_records (object_record_id, object_number, name, object_type, place_made, maker, location, perspective, public_access, fields_json, source_file) VALUES ('1831719', 'M1723', 'Uniform, Dorrigo District Rural School', 'Uniforms', NULL, NULL, NULL, 'HISTORY', 0, '{"object_number":"M1723","name":"Uniform, Dorrigo District Rural School","object_type":"Uniforms","dublin_core":"Physical Object","brief_description":"Green school blazer with gold trim and school badge embroidered on chest pocket. Green and gold striped school tie and white shirt. The blazer is made by The Challenge. \n\nWorn by donor''s daughters during the 1960s.","web_public_description":"Green school blazer with gold trim and school badge embroidered on chest pocket. Green and gold striped school tie and white shirt. \n\nWorn by donor''s daughters during the 1960s.","date_made":"1960s","general_notes_acquisition":"Donated by:\nMrs D Hollingsworth\nKarabin Street\nDorrigo","credit_line":"Donor: Mrs D Hollingsworth","comments":"DDM_M1720-d01.dng\nDDM_M1720-d01.tif\nDDM_M1720-d02.dng\nDDM_M1720-d02.tif\nDDM_M1720-d03.dng\nDDM_M1720-d03.tif\nDDM_M1720.md5","comments_date":"15/08/2023","comments_person":"A Long","general_flag_admin":"Digitised","current_condition_description":"Fair, worn condition."}', 'secondreport_xml_7f337cc921094b62b3bdd0725e70ec7c.xml');
INSERT INTO ehive_records (object_record_id, object_number, name, object_type, place_made, maker, location, perspective, public_access, fields_json, source_file) VALUES ('1831723', 'M1723', 'Honour Roll, North Dorrigo Public School', 'Honour boards', NULL, 'Wunderlich', 'Research Room', 'HISTORY', 0, '{"object_number":"M1723","name":"Honour Roll, North Dorrigo Public School","object_type":"Honour boards","dublin_core":"Physical Object","brief_description":"Bronze honour roll for former students of North Dorrigo Public School who served in the First World War. It is decorated with several patterns and scrolls, which divide the roll into three sections. At the top of the centre section is an oval plaque, inscribed ''NORTH DORRIGO/ PUBLIC/ SCHOOL''.  Below this is the dedication to service for the Empire, in raised letters. At the bottom of the centre section is a circular plaque inscribed with the NSW state crest. The 25 names on the roll are inscribed over two rectangular plaques, attached to the left and right sides of the board. \n\nThe Don Dorrigo Gazette and Guy Fawkes Advocate, 30 April 1921, reported on planning for the roll: ''The school honor roll, which will contain the names of all ex-pupils who served in the Great War, and which the Association has had in view for some considerable time is expected to be in the school by Empire Day, when it will be duly unveiled.''\n\nHowever, it was not until October 1921 that the roll went on display at a local store (Don Dorrigo Gazette, 15 October 1921). In the Gazette on 19 October, it was reported: ''Permission has been given by the Department to the Principal to alter the usual routine to permit the ceremony being performed in school hours. An invitation to all interested to be present is extended.''\n\nThe roll was officially unveiled at the school on 21 October 1921, by Mr Nelson. \n\nThe roll was designed by the Wunderlich Company of Sydney, NSW, a large Australian company specialising in the construction of tiles and pressed metal ceilings. Following the First World War, Wunderlich created a number of bronze honour rolls. \n\nNames on the roll can be viewed at: https://www.warmemorialsregister.nsw.gov.au/memorials/north-dorrigo-public-school-great-war-honour-roll","web_public_description":"Bronze honour roll for former students of North Dorrigo Public School who served in the First World War. It is decorated with several patterns and scrolls, which divide the roll into three sections. At the top of the centre section is an oval plaque, inscribed ''NORTH DORRIGO/ PUBLIC/ SCHOOL''.  Below this is the dedication to service for the Empire, in raised letters. At the bottom of the centre section is a circular plaque inscribed with the NSW state crest. The 25 names on the roll are inscribed over two rectangular plaques, attached to the left and right sides of the board. \n\nThe Don Dorrigo Gazette and Guy Fawkes Advocate, 30 April 1921, reported on planning for the roll: ''The school honor roll, which will contain the names of all ex-pupils who served in the Great War, and which the Association has had in view for some considerable time is expected to be in the school by Empire Day, when it will be duly unveiled.''\n\nHowever, it was not until October 1921 that the roll went on display at a local store (Don Dorrigo Gazette, 15 October 1921). In the Gazette on 19 October, it was reported: ''Permission has been given by the Department to the Principal to alter the usual routine to permit the ceremony being performed in school hours. An invitation to all interested to be present is extended.''\n\nThe roll was officially unveiled at the school on 21 October 1921, by Mr Nelson. \n\nThe roll was designed by the Wunderlich Company of Sydney, NSW, a large Australian company specialising in the construction of tiles and pressed metal ceilings. Following the First World War, Wunderlich created a number of bronze honour rolls. \n\nNames on the roll can be viewed at: https://www.warmemorialsregister.nsw.gov.au/memorials/north-dorrigo-public-school-great-war-honour-roll","primary_creator_maker":"Wunderlich","primary_creator_maker_role":"Manufacturer","date_made":"1921","location":"Research Room","location_history":"Research Room","medium_description":"Metal","inscription":"Inscribed ''IN HONOUR OF/ THE OLD BOYS OF/ THIS SCHOOL/ WHO SERVED/ THE EMPIRE/ IN THE GREAT WAR''.","measurement_description":"630mm L, 390mm W","association_keyword":"Wars","catalogued_date":"15/06/2023","comments":"DDM_M1723-d01.dng\nDDM_M1723-d01.tif\nDDM_M1723-d02.dng\nDDM_M1723-d02.tif\nDDM_M1723.md5","comments_date":"15/08/2023","comments_person":"A Long","general_flag_admin":"Digitised"}', 'secondreport_xml_7f337cc921094b62b3bdd0725e70ec7c.xml');
INSERT INTO ehive_records (object_record_id, object_number, name, object_type, place_made, maker, location, perspective, public_access, fields_json, source_file) VALUES ('1831725', 'M1724', 'Butter Wraps, Dorrigo Butter', 'Packaging', NULL, NULL, 'Verandah', 'HISTORY', 0, '{"object_number":"M1724","name":"Butter Wraps, Dorrigo Butter","object_type":"Packaging","dublin_core":"Physical Object","brief_description":"Roll of printed paper wrappers for Dorrigo Butter. Text reads ''DORRIGO/ [tree]/Choicest Pasteurised / BUTTER/ 1 LB NET REG NO 284D'' \n\nPrinted for the Central Dairy Co-Operative Society Ltd - Dorrigo Branch.","web_public_description":"Roll of printed paper wrappers for Dorrigo Butter. Text reads ''DORRIGO/ [tree]/ Choicest Pasteurised/ BUTTER/ 1 LB NET REG NO 284D'' \n\nPrinted for the Central Dairy Co-Operative Society Ltd - Dorrigo Branch.","location":"Verandah","location_history":"Verandah","location_history_date":"16/06/2023","location_history_notes":"Dairy display","medium_description":"Paper, ink","measurement_description":"Roll: 85mm H, 30mm W","association_keyword":"Agriculture","catalogued_date":"16/06/2023","comments":"DDM_M1724-col.dng\nDDM_M1724-col.tif\nDDM_M1724-d01.dng\nDDM_M1724-d01.tif\nDDM_M1724-d02.dng\nDDM_M1724-d02.tif\nDDM_M1724.md5","comments_date":"17/08/2023","comments_person":"A Long","general_flag_admin":"Digitised","current_condition_description":"Fair."}', 'secondreport_xml_7f337cc921094b62b3bdd0725e70ec7c.xml');
INSERT INTO ehive_records (object_record_id, object_number, name, object_type, place_made, maker, location, perspective, public_access, fields_json, source_file) VALUES ('838377', NULL, 'Signature Tablecloth', NULL, 'Dorrigo', 'Mary Jane Doust', NULL, 'HISTORY', 0, '{"accession_date":"2016","name":"Signature Tablecloth","dublin_core":"Physical Object","brief_description":"This unique white tablecloth is embroidered with the names of 150 people associated with the Methodist Church in Dorrigo from 1910 to 1918. It is made from 16 fine linen squares, which appear to be serviettes, joined together by lace insertions. The cloth includes the names of Methodist pastors and an Honour Roll of 41 men associated with these families who enlisted in the First World War. Many of these families and their descendants still live in the Dorrigo area. \n\nThe tablecloth was made and embroidered by Mary Jane Doust, nee Short, [1863 - 1962] one of Dorrigo’s early white settlers who lived with her husband Reuben on their farm “Glendon” at Little Plain, later known as North Dorrigo. This area was the first area settled in The Don Dorrigo Scrub.  Mary Jane, known as Minnie, was a devout Methodist. When they first settled in the area Church services were held in the Doust’s slab home and later Minnie played the church organ. \n \nTablecloths like this one, show the sewing, embroidery and design skills of its maker. This cloth has been carefully designed into four sections of four squares each. Each section has an embroidered heading underlined in chain stitch and all names are embroidered in stem stitch. Each linen square has mitred corners with drawn thread borders. \n\nThis tablecloth evidences the resourcefulness of rural women such as Minnie Doust who set about raising the necessary funds to purchase an organ for the North Dorrigo Methodist Church by encouraging the Methodist community to pay for their names to be embroidered on the cloth.  After completion the cloth was auctioned to raise further funds. \n    \nNeedlework has always been a popular and practical pursuit for women. It has provided a creative outlet and a practical one as demonstrated by Minnie Doust in using her needlework skills to raise money for her church. The tablecloth resonates with the local community and featured at the 110 year celebration of the Dorrigo Methodist Church in 2016. \n\nThe tablecloth now provides an enduring record of the families associated with the Methodist Church in the Dorrigo area and the young men who served their country and community during World War 1. Most of all, this cloth reflects the ingenuity and efforts of Minnie Doust in using materials on hand and her needlework skills to ‘crowd fund’ the purchase of a church organ for the Methodist community on the Dorrigo plateau. \n\nRuth Holmes                                                                                                                                                                                                                 27 August 2017","web_public_description":"This unique white tablecloth is embroidered with the names of 150 people associated with the Methodist Church in Dorrigo from 1910 to 1918. It is made from 16 fine linen squares, which appear to be serviettes, joined together by lace insertions. The cloth includes the names of Methodist pastors and an Honour Roll of 41 men associated with these families who enlisted in the First World War. Many of these families and their descendants still live in the Dorrigo area. \n\nThe tablecloth was made and embroidered by Mary Jane Doust, nee Short, [1863 - 1962] one of Dorrigo’s early white settlers who lived with her husband Reuben on their farm “Glendon” at Little Plain, later known as North Dorrigo. This area was the first area settled in The Don Dorrigo Scrub.  Mary Jane, known as Minnie, was a devout Methodist. When they first settled in the area Church services were held in the Doust’s slab home and later Minnie played the church organ.  \n\nTablecloths like this one, show the sewing, embroidery and design skills of its maker. This cloth has been carefully designed into four sections of four squares each. Each section has an embroidered heading underlined in chain stitch and all names are embroidered in stem stitch. Each linen square has mitred corners with drawn thread borders. \n\nThis tablecloth evidences the resourcefulness of rural women such as Minnie Doust who set about raising the necessary funds to purchase an organ for the North Dorrigo Methodist Church by encouraging the Methodist community to pay for their names to be embroidered on the cloth.  After completion the cloth was auctioned to raise further funds. \n    \nNeedlework has always been a popular and practical pursuit for women. It has provided a creative outlet and a practical one as demonstrated by Minnie Doust in using her needlework skills to raise money for her church. The tablecloth resonates with the local community and featured at the 110 year celebration of the Dorrigo Methodist Church in 2016. \n\nThe tablecloth now provides an enduring record of the families associated with the Methodist Church in the Dorrigo area and the young men who served their country and community during World War 1. Most of all, this cloth reflects the ingenuity and efforts of Minnie Doust in using materials on hand and her needlework skills to ‘crowd fund’ the purchase of a church organ for the Methodist community on the Dorrigo plateau. \n\nRuth Holmes \n27 August 2017","primary_creator_maker":"Mary Jane Doust","date_made":"1910-1919","place_made":"Dorrigo","medium_description":"Linen, cotton, lace","measurement_description":"1530mm L, 1530mm W","credit_line":"Donors: Chrissie and Alan Cummins"}', 'secondreport_xml_7f337cc921094b62b3bdd0725e70ec7c.xml');
